import{z as o,x as A,o as B,c as d,q as r,j as i,D as E,d as s,s as n,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"CI/CD","description":"","frontmatter":{"title":"CI/CD","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/swe-ci-cd.md","filePath":"cs/swe-ci-cd.md","lastUpdated":1791413859000}'),c={name:"cs/swe-ci-cd.md"};function p(C,a,D,F,m,h){const t=A("Mermaid");return B(),d("div",null,[a[2]||(a[2]=r('<h1 id="ci-cd" tabindex="-1">CI/CD <a class="header-anchor" href="#ci-cd" aria-label="Permalink to &quot;CI/CD&quot;">​</a></h1><div class="epigraph"><p>持续集成不是服务器上多跑一遍测试，而是把「主干随时可发布」从愿望改成机器在每个变更集上执行的断言。</p><footer>—— 据 Humble and Farley, Continuous Delivery, 2010；Beck, Test-Driven Development, 2003 整理</footer></div><p><a href="/cs/swe-build-systems">上一课</a>把构建做成内容寻址的动作图，同一份主干快照在任何机器得到同一产物。本课把这套判据装进自动执行的服务：合入前对候选变更跑门禁，合入后产物自动走发布路径。三层判据（<a href="/cs/swe-testing-strategy">测试策略：单元、集成与属性</a>）在这里从自觉变成制度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>本地绿不等于主干绿：各自本地绿、合并后红的语义冲突在<a href="/cs/swe-branching-changes">分支与变更管理</a>已经见过；本地与构建环境的漂移在密封性一课也见过。剩下的是制度缺口：需要一台不受本地状态污染的机器，对每个候选变更集执行同一套判据，并且让「没过门」的改动在物理上合不进去——门禁若可以顺手跳过，它就是装饰。</p><p><span class="marginnote">代个数看反馈时间的账：门禁 10 分钟，作者失败时还坐在原地，改几行重新推，间隔以分钟计；门禁 60 分钟，人早已切去写别的代码，一次失败打断两件事，修复与归因成本成倍涨。门禁快慢直接决定团队是小步走还是攒批走。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线把判据排成序列：候选变更进来，先静态检查（<a href="/cs/static-taint-analysis">静态与污点分析</a>的口径），再密封构建，再单元层，再集成层，全绿产出不可变产物（镜像分层见<a href="/cs/oci-image-layers">OCI 镜像层</a>）。多个变更并发时用合并队列：把队列里每个变更依次与最新主干组合验证，堵住「每个单独绿、叠起来红」的缝。合入后 CD 接管：同一产物逐环境晋级——dev、staging、prod——不在各环境重建；金丝雀放量，指标异常即回滚；没做完的功能用开关关着，口径见<a href="/cs/swe-branching-changes">分支与变更管理</a>。</p><p><span class="marginnote">术语翻译：金丝雀放量（canary）就是先让新版本服务约 1% 的真实流量，盯错误率与延迟等指标，正常再 10%、50% 地放大——名字来自矿工带金丝雀下井探毒气：它先出事，人还有时间撤。</span></p>',9)),(B(),i(l,null,{default:E(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E5%80%99%E9%80%89%E5%8F%98%E6%9B%B4%E9%9B%86%22%5D%20--%3E%20LINT%5B%22%E9%9D%99%E6%80%81%E6%A3%80%E6%9F%A5%22%5D%0A%20%20LINT%20--%3E%20BUILD%5B%22%E5%AF%86%E5%B0%81%E6%9E%84%E5%BB%BA%22%5D%0A%20%20BUILD%20--%3E%20TEST%5B%22%E5%8D%95%E5%85%83%E4%B8%8E%E9%9B%86%E6%88%90%E9%97%A8%E7%A6%81%22%5D%0A%20%20TEST%20--%3E%20Q%5B%22%E5%90%88%E5%B9%B6%E9%98%9F%E5%88%97%EF%BC%9A%E4%B8%8E%E6%9C%80%E6%96%B0%E4%B8%BB%E5%B9%B2%E7%BB%84%E5%90%88%22%5D%0A%20%20Q%20--%3E%20MAIN%5B%22%E4%B8%BB%E5%B9%B2%EF%BC%9A%E5%8F%AF%E5%8F%91%E5%B8%83%E5%BF%AB%E7%85%A7%22%5D%0A%20%20MAIN%20--%3E%20ART%5B%22%E4%B8%8D%E5%8F%AF%E5%8F%98%E4%BA%A7%E7%89%A9%22%5D%0A%20%20ART%20--%3E%20CAN%5B%22%E9%87%91%E4%B8%9D%E9%9B%80%E6%94%BE%E9%87%8F%22%5D%0A%20%20CAN%20--%3E%7C%E6%8C%87%E6%A0%87%E5%BC%82%E5%B8%B8%7C%20RB%5B%22%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20CAN%20--%3E%7C%E6%AD%A3%E5%B8%B8%7C%20PROD%5B%22%E5%85%A8%E9%87%8F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"门禁的经济学在反馈时间：门禁快，人就小步合入，失败归因小；门禁慢，人就攒批，revert 粒度跟着变大。上一课的缓存键在这里兑现：门禁只重算受影响的动作，分钟级预算才守得住。flaky 测试是门禁的毒药：它让红不再必然指示回归，团队开始重跑，而重跑成功一次，门禁的可信度就降一分。治理办法是把重试隔离并记录：重试预算固定，二次失败必须阻塞。跳过门禁要有留痕与授权，否则断言退化成装饰。",-1)),a[5]||(a[5]=e("p",null,"合并队列怎么堵「单独绿、叠起来红」，把队列展开看。",-1)),(B(),i(l,null,{default:E(()=>[n(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20M0%5B%22%E4%B8%BB%E5%B9%B2%20M0%EF%BC%9A%E5%BD%93%E5%89%8D%E7%BB%BF%22%5D%20--%3E%20A%5B%22%E9%98%9F%E9%A6%96%20A%EF%BC%9A%E8%B7%91%20M0%2BA%20%E9%97%A8%E7%A6%81%22%5D%0A%20%20A%20--%3E%20G1%7B%22A%20%E7%BB%BF%E5%90%97%22%7D%0A%20%20G1%20--%20%22%E7%BB%BF%22%20--%3E%20M1%5B%22A%20%E8%BF%9B%E4%B8%BB%E5%B9%B2%EF%BC%8C%E5%BE%97%20M1%22%5D%0A%20%20M1%20--%3E%20B%5B%22%E9%98%9F%E9%A6%96%20B%EF%BC%9A%E8%B7%91%20M1%2BB%20%E9%97%A8%E7%A6%81%22%5D%0A%20%20B%20--%3E%20G2%7B%22B%20%E7%BB%BF%E5%90%97%22%7D%0A%20%20G2%20--%20%22%E7%BA%A2%EF%BC%88%E5%8F%AF%E8%83%BD%E4%B8%8E%20A%20%E7%9B%B8%E5%86%B2%EF%BC%89%22%20--%3E%20POP%5B%22B%20%E5%BC%B9%E5%87%BA%E9%98%9F%E5%88%97%E9%80%80%E5%9B%9E%E4%BD%9C%E8%80%85%EF%BC%8CM1%20%E4%B8%8D%E5%8F%97%E6%B1%A1%E6%9F%93%22%5D%0A%20%20G2%20--%20%22%E7%BB%BF%22%20--%3E%20M2%5B%22B%20%E8%BF%9B%E4%B8%BB%E5%B9%B2%EF%BC%8C%E5%BE%97%20M2%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">初学者容易把 CD 理解成「每次合入自动直上生产」。实际机制是同一份不可变产物逐环境晋级：dev、staging 各层看过，生产先吃 1% 金丝雀；出问题回滚的是流量与指针，不在各环境重新构建——重建就丢掉了「测过的就是发布的」这条保证。</span></p><p><span class="marginnote">量化：单个测试失败率 1%，一百个变更的门禁里期望放大约一次假红；按至少一次口径 \\(1-(1-0.01)^{100}\\approx 0.63\\)。若「重跑变绿就放行」成为习惯，真回归混在重跑里被放行的概率同步上升——重试必须留痕，才有得查。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>CI 不替代评审：门禁判行为，评审判意图与设计，两者在合并队列里会合。部署形态的对照（滚动、蓝绿、金丝雀的适用面）与发布编排不展开；供应链攻击面——依赖混淆一类——见<a href="/cs/dependency-confusion">依赖混淆</a>，安全扫描管线只点名。门禁时长超过人愿意等的阈值，绕过就开始：预算是制度的一部分，不是性能细节。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CI 是制度化的判据执行：没过门的改动在物理上进不了主干。</li><li>合并队列堵「单独绿、叠起来红」；产物不可变，环境只晋级不重建。</li><li>反馈时间决定合入批量；缓存使门禁守住分钟级预算。</li><li>flaky 用隔离重试与固定预算治理，重跑变绿不等于回归不存在。</li><li>跳过门禁要留痕授权，否则断言沦为装饰。</li><li>出处：Humble and Farley, <em>Continuous Delivery</em>, 2010；判据分层见<a href="/cs/swe-testing-strategy">测试策略：单元、集成与属性</a>。</li></ul>',6))])}const T=o(c,[["render",p]]);export{u as __pageData,T as default};
